import{_ as r,c as a,o as t,a2 as o}from"./chunks/framework.mqLGQ42V.js";const v=JSON.parse('{"title":"Defold - Rive 游戏运行时","description":"Game Runtimes Defold 是一个免费的、跨平台的游戏引擎，它内置了对 Rive 图形的支持，允许你轻松地将 Rive 集成到你的 Defold 游戏中。","frontmatter":{"title":"Defold - Rive 游戏运行时","description":"Game Runtimes Defold 是一个免费的、跨平台的游戏引擎，它内置了对 Rive 图形的支持，允许你轻松地将 Rive 集成到你的 Defold 游戏中。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 游戏运行时, Defold"}]]},"headers":[],"relativePath":"games/defold.md","filePath":"games/defold.md","lastUpdated":1774838907000}'),l={name:"games/defold.md"};function i(n,e,d,p,s,f){return t(),a("div",null,[...e[0]||(e[0]=[o('<p>Game Runtimes</p><h1 id="defold" tabindex="-1">Defold <a class="header-anchor" href="#defold" aria-label="Permalink to &quot;Defold&quot;">​</a></h1><p><a href="https://defold.com/" target="_blank" rel="noreferrer">Defold</a> 是一个免费的、跨平台的游戏引擎，它内置了对 Rive 图形的支持，允许你轻松地将 Rive 集成到你的 Defold 游戏中。</p><p>Rive 集成由 Defold 团队管理。</p><p>有关在 Defold 中使用 Rive 的更多信息，请参阅 <a href="https://defold.com/extension-rive/" target="_blank" rel="noreferrer">官方 Defold 文档</a>。在那里，你将找到有关设置 Rive 图形以及在 Defold 引擎中使用它们的最佳实践的综合指南。</p><h3 id="​-渲染-rendering" tabindex="-1"><a href="#rendering">​</a> 渲染 (Rendering) <a class="header-anchor" href="#​-渲染-rendering" aria-label="Permalink to &quot;[​](#rendering) 渲染 (Rendering)&quot;">​</a></h3><p>Defold 原生继承了 <a href="https://rive.app/renderer" target="_blank" rel="noreferrer">Rive 渲染器</a>，这意味着 Defold 中的 Rive 图形由 Rive 编辑器中使用的同一渲染器渲染。这种原生集成提供了几个好处：</p><ul><li><strong>性能</strong>: Rive 渲染器是为 Rive 内容、动画和运行时定制的。允许你以极快的速度绘制前所未有数量的矢量图形。<a href="https://rive.app/blog/rive-renderer-now-open-source-and-available-on-all-platforms" target="_blank" rel="noreferrer">阅读更多</a>。</li><li><strong>质量</strong>: 无论缩放、分辨率或设备如何，图形都保持清晰。</li><li><strong>一致性</strong>: 你的图形在编辑器和运行时的外观完全相同。</li><li><strong>功能支持</strong>: 你还将受益于即将推出的 Rive 功能，例如只有通过 Rive 渲染器才能实现的模糊和阴影。</li></ul><h3 id="​-支持-support" tabindex="-1"><a href="#support">​</a> 支持 (Support) <a class="header-anchor" href="#​-支持-support" aria-label="Permalink to &quot;[​](#support) 支持 (Support)&quot;">​</a></h3><p>如果你对 Defold 中的 Rive 有任何疑问，请随时探索他们的 <a href="https://forum.defold.com/" target="_blank" rel="noreferrer">社区论坛</a> 或联系他们的支持团队。如果你认为问题出在 Rive，请通过 <a href="https://community.rive.app/c/support/" target="_blank" rel="noreferrer">我们的社区</a> 联系我们。</p><p><a href="https://help.rive.app/game-runtimes/unity/rive-events" target="_blank" rel="noreferrer">Rive 事件</a></p>',11)])])}const m=r(l,[["render",i]]);export{v as __pageData,m as default};
